var i=`0471-baklava`;var t=`world-0471`;var n=`TR`;var o=`western-asia`;var s=8;var r=82;var l={en:`Baklava`,ua:`Пахлава по-турецьки`};var g={en:`A traditional dish from Türkiye, centered on phyllo pastry, pistachio, lemon juice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: тісто філо, фісташка, лимонний сік. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:22,i:[[`phyllo-pastry`,480,`g`],[`pistachio`,260,`g`],[`unsalted-butter`,230,`g`]]},{en:`Bake in a preheated 180°C oven for about 42 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 42 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:42,i:[]},{en:`Pour warm syrup over cooled crisp baklava or cool syrup over hot pastry; allow time for absorption without sogginess.`,ua:`Полийте охолоджену хрустку пахлаву теплим сиропом або гарячу пахлаву холодним сиропом; дайте просочитися, не перезволожуючи.`,t:[`reducing-sauce`],m:14,i:[[`white-granulated-sugar`,290,`g`],[`water`,240,`ml`],[`lemon-juice`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[]}];var d={slug:i,id:t,country:`TR`,region:o,servings:8,minutes:82,title:l,text:g,steps:u};export{n as country,d as default,t as id,r as minutes,o as region,s as servings,i as slug,u as steps,g as text,l as title};